/// Callback for receiving progress notifications during tool execution.
///
/// The callback receives the progress value, optional total, and optional message.
pub type ProgressCallback<'a> = &'a mut dyn FnMut(f64, Option<f64>, Option<&str>);

/// Erased, cancellation-aware result future returned by a reverse handler.
pub type ReverseRequestFuture<'cx, T> = Pin<Box<dyn Future<Output = McpResult<T>> + Send + 'cx>>;

/// Async handler for a server-initiated `sampling/createMessage` request.
///
/// The connection supplies a child [`Cx`] that is aborted when the matching
/// exact-2024 cancellation notification arrives. Implementations must use that
/// context for every awaitable effect.
pub type SamplingRequestHandler = Arc<
    dyn for<'cx> Fn(
            &'cx Cx,
            ReverseRequestCancellation,
            CreateMessageParams,
        ) -> ReverseRequestFuture<'cx, CreateMessageResult>
        + Send
        + Sync,
>;

/// Async handler for a server-initiated `roots/list` request.
pub type RootsRequestHandler = Arc<
    dyn for<'cx> Fn(
            &'cx Cx,
            ReverseRequestCancellation,
            ListRootsParams,
        ) -> ReverseRequestFuture<'cx, ListRootsResult>
        + Send
        + Sync,
>;

/// Async handler for a modern `sampling/createMessage` reverse request.
pub type ModernSamplingRequestHandler = Arc<
    dyn for<'cx> Fn(
            &'cx Cx,
            ReverseRequestCancellation,
            FinalCreateMessageParams,
        ) -> ReverseRequestFuture<'cx, FinalCreateMessageResult>
        + Send
        + Sync,
>;

/// Async handler for a modern `roots/list` reverse request.
pub type ModernRootsRequestHandler = Arc<
    dyn for<'cx> Fn(
            &'cx Cx,
            ReverseRequestCancellation,
            FinalEmbeddedRootsListParams,
        ) -> ReverseRequestFuture<'cx, FinalEmbeddedRootsListResult>
        + Send
        + Sync,
>;

/// Async handler for a modern `elicitation/create` reverse request.
pub type ModernElicitationRequestHandler = Arc<
    dyn for<'cx> Fn(
            &'cx Cx,
            ReverseRequestCancellation,
            ElicitRequestParams,
        ) -> ReverseRequestFuture<'cx, ElicitResult>
        + Send
        + Sync,
>;

/// Configurable handlers for reverse requests received from a live MCP server.
#[derive(Clone, Default)]
pub struct ReverseRequestHandlers {
    sampling_create_message: Option<SamplingRequestHandler>,
    roots_list: Option<RootsRequestHandler>,
    modern_sampling_create_message: Option<ModernSamplingRequestHandler>,
    modern_roots_list: Option<ModernRootsRequestHandler>,
    modern_elicitation_create: Option<ModernElicitationRequestHandler>,
}

impl ReverseRequestHandlers {
    /// Creates an empty handler set. Unconfigured methods receive `MethodNotFound`.
    #[must_use]
    pub const fn new() -> Self {
        Self {
            sampling_create_message: None,
            roots_list: None,
            modern_sampling_create_message: None,
            modern_roots_list: None,
            modern_elicitation_create: None,
        }
    }

    /// Configures handling for `sampling/createMessage`.
    #[must_use]
    pub fn with_sampling_create_message<F>(mut self, handler: F) -> Self
    where
        F: for<'cx> Fn(
                &'cx Cx,
                ReverseRequestCancellation,
                CreateMessageParams,
            ) -> ReverseRequestFuture<'cx, CreateMessageResult>
            + Send
            + Sync
            + 'static,
    {
        self.sampling_create_message = Some(Arc::new(handler));
        self
    }

    /// Configures handling for `roots/list`.
    #[must_use]
    pub fn with_roots_list<F>(mut self, handler: F) -> Self
    where
        F: for<'cx> Fn(
                &'cx Cx,
                ReverseRequestCancellation,
                ListRootsParams,
            ) -> ReverseRequestFuture<'cx, ListRootsResult>
            + Send
            + Sync
            + 'static,
    {
        self.roots_list = Some(Arc::new(handler));
        self
    }

    /// Configures handling for modern `sampling/createMessage`.
    #[must_use]
    pub fn with_modern_sampling_create_message<F>(mut self, handler: F) -> Self
    where
        F: for<'cx> Fn(
                &'cx Cx,
                ReverseRequestCancellation,
                FinalCreateMessageParams,
            ) -> ReverseRequestFuture<'cx, FinalCreateMessageResult>
            + Send
            + Sync
            + 'static,
    {
        self.modern_sampling_create_message = Some(Arc::new(handler));
        self
    }

    /// Configures handling for modern `roots/list`.
    #[must_use]
    pub fn with_modern_roots_list<F>(mut self, handler: F) -> Self
    where
        F: for<'cx> Fn(
                &'cx Cx,
                ReverseRequestCancellation,
                FinalEmbeddedRootsListParams,
            ) -> ReverseRequestFuture<'cx, FinalEmbeddedRootsListResult>
            + Send
            + Sync
            + 'static,
    {
        self.modern_roots_list = Some(Arc::new(handler));
        self
    }

    /// Configures handling for modern `elicitation/create`.
    #[must_use]
    pub fn with_modern_elicitation_create<F>(mut self, handler: F) -> Self
    where
        F: for<'cx> Fn(
                &'cx Cx,
                ReverseRequestCancellation,
                ElicitRequestParams,
            ) -> ReverseRequestFuture<'cx, ElicitResult>
            + Send
            + Sync
            + 'static,
    {
        self.modern_elicitation_create = Some(Arc::new(handler));
        self
    }

    pub(crate) fn is_empty(&self) -> bool {
        self.sampling_create_message.is_none() && self.roots_list.is_none()
    }

    pub(crate) fn has_modern_handlers(&self) -> bool {
        self.modern_sampling_create_message.is_some()
            || self.modern_roots_list.is_some()
            || self.modern_elicitation_create.is_some()
    }

    /// Fulfills one peer `input_required` result by invoking the matching
    /// installed modern reverse handlers locally.
    ///
    /// This is the modern MRTR path: the server asked for sampling, roots, or
    /// elicitation inside `inputRequests`, and the client supplies
    /// `inputResponses` on the next `tools/call` without sending reverse
    /// JSON-RPC.
    pub(crate) fn respond_to_input_required(
        &self,
        cx: &Cx,
        input_required: &InputRequiredResult,
    ) -> McpResult<MrtrInputResponses> {
        let Some(input_requests) = input_required.input_requests() else {
            return Ok(MrtrInputResponses::new());
        };
        let mut responses = MrtrInputResponses::new();
        for member in input_requests.members() {
            let wire = exact_json_to_serde(&member.value).map_err(|error| {
                McpError::invalid_params(format!(
                    "MRTR input request {} is not valid JSON: {error}",
                    member.name
                ))
            })?;
            let request: FinalEmbeddedInputRequest =
                serde_json::from_value(wire).map_err(|error| {
                    McpError::invalid_params(format!(
                        "MRTR input request {} is not a final embedded descriptor: {error}",
                        member.name
                    ))
                })?;
            let value = self.invoke_embedded_input_request(cx, &member.name, request)?;
            responses.insert(member.name.clone(), value);
        }
        Ok(responses)
    }

    /// Async counterpart of [`Self::respond_to_input_required`] for callers
    /// already on an asupersync runtime. Nested `block_on` would cancel.
    pub(crate) async fn respond_to_input_required_async(
        &self,
        cx: &Cx,
        input_required: &InputRequiredResult,
    ) -> McpResult<MrtrInputResponses> {
        let Some(input_requests) = input_required.input_requests() else {
            return Ok(MrtrInputResponses::new());
        };
        let mut responses = MrtrInputResponses::new();
        for member in input_requests.members() {
            let wire = exact_json_to_serde(&member.value).map_err(|error| {
                McpError::invalid_params(format!(
                    "MRTR input request {} is not valid JSON: {error}",
                    member.name
                ))
            })?;
            let request: FinalEmbeddedInputRequest =
                serde_json::from_value(wire).map_err(|error| {
                    McpError::invalid_params(format!(
                        "MRTR input request {} is not a final embedded descriptor: {error}",
                        member.name
                    ))
                })?;
            let value = self
                .invoke_embedded_input_request_async(cx, &member.name, request)
                .await?;
            responses.insert(member.name.clone(), value);
        }
        Ok(responses)
    }

    fn invoke_embedded_input_request(
        &self,
        cx: &Cx,
        input_key: &str,
        request: FinalEmbeddedInputRequest,
    ) -> McpResult<serde_json::Value> {
        match request {
            FinalEmbeddedInputRequest::Sampling(params) => {
                let Some(handler) = self.modern_sampling_create_message.as_ref() else {
                    return Err(McpError::invalid_params(format!(
                        "MRTR input request {input_key} requires an installed sampling/createMessage reverse handler"
                    )));
                };
                let result = invoke_locked_reverse_request_handler(
                    cx,
                    handler,
                    ReverseRequestCancellation::new(),
                    final_create_message_params_from_embedded(params),
                )?;
                serde_json::to_value(result).map_err(|error| {
                    McpError::internal_error(format!(
                        "MRTR sampling input response could not serialize: {error}"
                    ))
                })
            }
            FinalEmbeddedInputRequest::Roots(params) => {
                let Some(handler) = self.modern_roots_list.as_ref() else {
                    return Err(McpError::invalid_params(format!(
                        "MRTR input request {input_key} requires an installed roots/list reverse handler"
                    )));
                };
                let result = invoke_locked_reverse_request_handler(
                    cx,
                    handler,
                    ReverseRequestCancellation::new(),
                    params,
                )?;
                serde_json::to_value(result).map_err(|error| {
                    McpError::internal_error(format!(
                        "MRTR roots input response could not serialize: {error}"
                    ))
                })
            }
            FinalEmbeddedInputRequest::Elicitation(params) => {
                let Some(handler) = self.modern_elicitation_create.as_ref() else {
                    return Err(McpError::invalid_params(format!(
                        "MRTR input request {input_key} requires an installed elicitation/create reverse handler"
                    )));
                };
                let result = invoke_locked_reverse_request_handler(
                    cx,
                    handler,
                    ReverseRequestCancellation::new(),
                    elicit_request_params_from_embedded(input_key, params),
                )?;
                serde_json::to_value(result).map_err(|error| {
                    McpError::internal_error(format!(
                        "MRTR elicitation input response could not serialize: {error}"
                    ))
                })
            }
        }
    }

    async fn invoke_embedded_input_request_async(
        &self,
        cx: &Cx,
        input_key: &str,
        request: FinalEmbeddedInputRequest,
    ) -> McpResult<serde_json::Value> {
        match request {
            FinalEmbeddedInputRequest::Sampling(params) => {
                let Some(handler) = self.modern_sampling_create_message.as_ref() else {
                    return Err(McpError::invalid_params(format!(
                        "MRTR input request {input_key} requires an installed sampling/createMessage reverse handler"
                    )));
                };
                let result = handler(
                    cx,
                    ReverseRequestCancellation::new(),
                    final_create_message_params_from_embedded(params),
                )
                .await?;
                serde_json::to_value(result).map_err(|error| {
                    McpError::internal_error(format!(
                        "MRTR sampling input response could not serialize: {error}"
                    ))
                })
            }
            FinalEmbeddedInputRequest::Roots(params) => {
                let Some(handler) = self.modern_roots_list.as_ref() else {
                    return Err(McpError::invalid_params(format!(
                        "MRTR input request {input_key} requires an installed roots/list reverse handler"
                    )));
                };
                let result = handler(cx, ReverseRequestCancellation::new(), params).await?;
                serde_json::to_value(result).map_err(|error| {
                    McpError::internal_error(format!(
                        "MRTR roots input response could not serialize: {error}"
                    ))
                })
            }
            FinalEmbeddedInputRequest::Elicitation(params) => {
                let Some(handler) = self.modern_elicitation_create.as_ref() else {
                    return Err(McpError::invalid_params(format!(
                        "MRTR input request {input_key} requires an installed elicitation/create reverse handler"
                    )));
                };
                let result = handler(
                    cx,
                    ReverseRequestCancellation::new(),
                    elicit_request_params_from_embedded(input_key, params),
                )
                .await?;
                serde_json::to_value(result).map_err(|error| {
                    McpError::internal_error(format!(
                        "MRTR elicitation input response could not serialize: {error}"
                    ))
                })
            }
        }
    }

    /// Adds the exact 2024-11-05 client capabilities implied by these
    /// callbacks. Roots-list-change remains disabled because registering a
    /// roots handler does not authorize the client to originate change events.
    pub(crate) fn derive_modern_capabilities(&self, capabilities: &mut ClientCapabilities) {
        if self.modern_sampling_create_message.is_some() {
            capabilities.sampling.get_or_insert(SamplingCapability {});
        }
        if self.modern_roots_list.is_some() {
            capabilities.roots.get_or_insert(RootsCapability {
                list_changed: false,
            });
        }
        if self.modern_elicitation_create.is_some() {
            capabilities
                .elicitation
                .get_or_insert(ElicitationCapability::both());
        }
    }

    pub(crate) fn derive_legacy_capabilities(&self, capabilities: &mut ClientCapabilities) {
        if self.sampling_create_message.is_some() {
            capabilities.sampling.get_or_insert(SamplingCapability {});
        }
        if self.roots_list.is_some() {
            capabilities.roots.get_or_insert(RootsCapability {
                list_changed: false,
            });
        }
    }

    /// Ensures that an exact-2024 callback configuration and its advertised
    /// capabilities describe precisely the same server-callable surface.
    pub(crate) fn validate_legacy_capabilities(
        &self,
        capabilities: &ClientCapabilities,
    ) -> McpResult<()> {
        if self.sampling_create_message.is_some() != capabilities.sampling.is_some() {
            return Err(McpError::invalid_params(
                "MCP 2024-11-05 sampling callback configuration must match the advertised sampling capability",
            ));
        }
        match (&self.roots_list, &capabilities.roots) {
            // `roots/listChanged` authorizes a separate client-originated
            // notification. It does not narrow the server's authority to
            // request `roots/list`, so both values are valid when the
            // callable roots handler is present.
            (Some(_), Some(_)) => {}
            (Some(_), None) | (None, Some(_)) => {
                return Err(McpError::invalid_params(
                    "MCP 2024-11-05 roots callback configuration must match the advertised roots capability",
                ));
            }
            (None, None) => {}
        }
        if capabilities.elicitation.is_some() {
            return Err(McpError::invalid_params(
                "MCP 2024-11-05 does not define an elicitation client capability",
            ));
        }
        Ok(())
    }
}
#[cfg(feature = "websocket-experimental")]
use fastmcp_transport::websocket::{AsyncWsClientRecvHalf, AsyncWsClientSendHalf};
use fastmcp_transport::{
    ClientTransportRecvHalf, ReceivedTransportFrame, StdioRecvHalf, StdioSendHalf, StdioTransport,
    Transport, TransportError, TransportRecvHalf, TransportSendHalf,
};

use crate::cache::{FinalCachePageLookup, final_cache_hints};
