    /// Calls one tool under a caller-owned cancellation domain.
    ///
    /// Installed modern reverse handlers fulfill `input_required` the same way
    /// as [`Self::call_tool`].
    pub async fn call_tool_with_cancellation(
        &mut self,
        cx: &Cx,
        cancellation: &McpRequestCancellation,
        name: &str,
        arguments: serde_json::Value,
    ) -> McpResult<CoreResult>
    where
        IO: Send + 'static,
    {
        self.follow_installed_mrtr(
            cx,
            Some(cancellation),
            "tools/call",
            serde_json::json!({ "name": name, "arguments": arguments }),
        )
        .await
    }

    /// Calls one tool and admits request-scoped `notifications/progress` for
    /// the supplied progress marker.
    ///
    /// Drain those frames with [`Self::take_final_progress_notifications`].
    pub async fn call_tool_with_progress_marker(
        &mut self,
        cx: &Cx,
        name: &str,
        arguments: serde_json::Value,
        progress_marker: ProgressMarker,
    ) -> McpResult<CoreResult>
    where
        IO: Send + 'static,
    {
        let token = serde_json::to_value(progress_marker).map_err(|_| {
            McpError::internal_error("WebSocket progress token could not be encoded")
        })?;
        self.follow_installed_mrtr(
            cx,
            None,
            "tools/call",
            serde_json::json!({
                "name": name,
                "arguments": arguments,
                "_meta": { "progressToken": token },
            }),
        )
        .await
    }

    async fn follow_installed_mrtr(
        &mut self,
        cx: &Cx,
        cancellation: Option<&McpRequestCancellation>,
        method: &str,
        original_parameters: serde_json::Value,
    ) -> McpResult<CoreResult>
    where
        IO: Send + 'static,
    {
        let handlers = self
            .reverse_request_handlers
            .has_modern_handlers()
            .then(|| self.reverse_request_handlers.clone());
        let mut parameters = original_parameters.clone();
        let mut rounds = 0_usize;
        loop {
            let result = match cancellation {
                Some(cancellation) => {
                    self.request_core_verb_with_cancellation(cx, cancellation, method, parameters)
                        .await?
                }
                None => self.request_core_verb(cx, method, parameters).await?,
            };
            let Some(input_required) = mrtr_input_required_for_method(method, &result) else {
                return Ok(result);
            };
            let Some(handlers) = handlers.as_ref() else {
                return Ok(result);
            };
            if rounds >= MAX_MRTR_CONTINUATION_ROUNDS {
                return Err(McpError::invalid_request(
                    "MRTR continuation-round limit exceeded",
                ));
            }
            rounds += 1;
            let input_responses = handlers
                .respond_to_input_required_async(cx, input_required)
                .await?;
            parameters = mrtr_retry_parameters(
                original_parameters.clone(),
                input_required,
                input_responses,
            )?;
        }
    }

    /// Sends one admitted generic MCP 2026-07-28 extension request.
    ///
    /// The extension registry and retained discovery must agree that `method`
    /// is a client-to-server method before this client allocates an ID or sends
    /// a WebSocket frame. Exact-2024 sessions reject at that same no-contact
    /// boundary through the immutable session admission gate.
    pub async fn request_final_extension(
        &mut self,
        cx: &Cx,
        extension_id: &fastmcp_protocol::ExtensionId,
        method: &str,
        parameters: serde_json::Value,
    ) -> McpResult<serde_json::Value>
    where
        IO: Send + 'static,
    {
        self.session
            .admit_final_extension_method(extension_id, method)?;
        if cx.checkpoint().is_err() {
            return Err(McpError::request_cancelled());
        }
        let parameters = self.with_modern_request_metadata(parameters)?;
        let request_id = self.allocate_request_id()?;
        let received = self
            .request_admitted_with_raw_result(
                cx,
                JsonRpcRequest::new(method, Some(parameters), request_id),
                None,
            )
            .await?;
        if let Some(error) = received.response.error {
            return Err(json_rpc_error_to_mcp(error));
        }
        let source = received.raw_result.ok_or_else(|| {
            McpError::invalid_request(
                "WebSocket final extension response has no admitted result source",
            )
        })?;
        serde_json::from_str(&source).map_err(|_| {
            McpError::invalid_request("WebSocket final extension response result is not valid JSON")
        })
    }

    /// Calls a modern tool and follows bounded input-required MRTR rounds.
    ///
    /// The supplied deadline covers every request in the operation; a retry
    /// cannot restart the caller's absolute time budget.
    pub async fn call_tool_with_mrtr_retry<F>(
        &mut self,
        cx: &Cx,
        deadline: Instant,
        name: &str,
        arguments: serde_json::Value,
        mut respond: F,
    ) -> McpResult<FinalCoreResult>
    where
        F: FnMut(&InputRequiredResult) -> McpResult<MrtrInputResponses>,
        IO: Send + 'static,
    {
        self.require_modern("tools/call")?;
        let limits =
            MrtrDriverLimits::new(MAX_MRTR_CONTINUATION_ROUNDS, MAX_MRTR_TOTAL_INPUT_RESPONSES)?;
        let mut driver = MrtrDriver::new(cx, deadline, limits)?;
        let original_parameters = serde_json::json!({
            "name": name,
            "arguments": arguments,
        });
        let mut parameters = original_parameters.clone();

        loop {
            driver.before_request()?;
            let result = self
                .request_final_core(cx, "tools/call", parameters)
                .await?;
            let Some(input_required) = mrtr_input_required_for_method("tools/call", &result) else {
                let CoreResult::Final(result) = result else {
                    return Err(McpError::invalid_request(
                        "Modern WebSocket MRTR received an exact-legacy result",
                    ));
                };
                return require_terminal_websocket_mrtr_result("tools/call", result);
            };
            driver.begin_continuation()?;
            let input_responses = respond(input_required)?;
            let input_response_count = input_responses.len();
            parameters = mrtr_retry_parameters(
                original_parameters.clone(),
                input_required,
                input_responses,
            )?;
            driver.admit_input_responses(input_response_count)?;
        }
    }

