    #[cfg(feature = "websocket-experimental")]
    fn async_websocket_pair() -> (
        asupersync::net::tcp::VirtualTcpStream,
        asupersync::net::tcp::VirtualTcpStream,
    ) {
        let client_addr: SocketAddr = "127.0.0.1:45101".parse().expect("client address");
        let server_addr: SocketAddr = "127.0.0.1:45102".parse().expect("server address");
        asupersync::net::tcp::VirtualTcpStream::pair(client_addr, server_addr)
    }

    /// Counts terminal RFC 6455 Close-frame elections on the client writer.
    /// The split receive and send halves share that writer, so exactly one
    /// count proves teardown did not run twice after a handshake failure.
    #[cfg(feature = "websocket-experimental")]
    struct CloseCountingIo {
        inner: asupersync::net::tcp::VirtualTcpStream,
        close_frames: Arc<AtomicUsize>,
    }

    #[cfg(feature = "websocket-experimental")]
    impl CloseCountingIo {
        fn new(
            inner: asupersync::net::tcp::VirtualTcpStream,
            close_frames: Arc<AtomicUsize>,
        ) -> Self {
            Self {
                inner,
                close_frames,
            }
        }
    }

    #[cfg(feature = "websocket-experimental")]
    impl AsyncRead for CloseCountingIo {
        fn poll_read(
            self: Pin<&mut Self>,
            cx: &mut Context<'_>,
            buf: &mut ReadBuf<'_>,
        ) -> Poll<io::Result<()>> {
            Pin::new(&mut self.get_mut().inner).poll_read(cx, buf)
        }
    }

    #[cfg(feature = "websocket-experimental")]
    impl AsyncWrite for CloseCountingIo {
        fn poll_write(
            self: Pin<&mut Self>,
            cx: &mut Context<'_>,
            bytes: &[u8],
        ) -> Poll<io::Result<usize>> {
            let this = self.get_mut();
            if bytes.first().is_some_and(|byte| byte & 0x0F == 0x08) {
                this.close_frames.fetch_add(1, Ordering::SeqCst);
            }
            Pin::new(&mut this.inner).poll_write(cx, bytes)
        }

        fn poll_flush(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
            Pin::new(&mut self.get_mut().inner).poll_flush(cx)
        }

        fn poll_shutdown(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
            Pin::new(&mut self.get_mut().inner).poll_shutdown(cx)
        }
    }

    #[cfg(feature = "websocket-experimental")]
    fn close_counting_async_websocket_pair() -> (
        CloseCountingIo,
        asupersync::net::tcp::VirtualTcpStream,
        Arc<AtomicUsize>,
    ) {
        let (client, peer) = async_websocket_pair();
        let close_frames = Arc::new(AtomicUsize::new(0));
        (
            CloseCountingIo::new(client, Arc::clone(&close_frames)),
            peer,
            close_frames,
        )
    }

    /// Allows discovery and the committed request through, then makes the
    /// cancellation notification's text-frame write remain pending forever.
    /// Close frames remain writable so the production timeout path can settle
    /// its transport without a detached sender.
    #[cfg(feature = "websocket-experimental")]
    struct StalledCancellationWriteIo {
        inner: asupersync::net::tcp::VirtualTcpStream,
        sent_text_frames: usize,
    }

    #[cfg(feature = "websocket-experimental")]
    impl AsyncRead for StalledCancellationWriteIo {
        fn poll_read(
            self: Pin<&mut Self>,
            cx: &mut Context<'_>,
            buf: &mut ReadBuf<'_>,
        ) -> Poll<io::Result<()>> {
            Pin::new(&mut self.get_mut().inner).poll_read(cx, buf)
        }
    }

    #[cfg(feature = "websocket-experimental")]
    impl AsyncWrite for StalledCancellationWriteIo {
        fn poll_write(
            self: Pin<&mut Self>,
            cx: &mut Context<'_>,
            bytes: &[u8],
        ) -> Poll<io::Result<usize>> {
            let this = self.get_mut();
            if bytes.first().is_some_and(|byte| byte & 0x0F == 0x01) {
                if this.sent_text_frames >= 2 {
                    return Poll::Pending;
                }
                this.sent_text_frames += 1;
            }
            Pin::new(&mut this.inner).poll_write(cx, bytes)
        }

        fn poll_flush(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
            Pin::new(&mut self.get_mut().inner).poll_flush(cx)
        }

        fn poll_shutdown(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
            Pin::new(&mut self.get_mut().inner).poll_shutdown(cx)
        }
    }

    #[cfg(feature = "websocket-experimental")]
    fn stalled_cancellation_async_websocket_pair() -> (
        StalledCancellationWriteIo,
        asupersync::net::tcp::VirtualTcpStream,
    ) {
        let (client, peer) = async_websocket_pair();
        (
            StalledCancellationWriteIo {
                inner: client,
                sent_text_frames: 0,
            },
            peer,
        )
    }

